// 6ixNetworks server — Node 18+ (built-in fetch; one optional dep, undici,
// only used when UPSTREAM_PROXY is set)
// Run: node server.js   (uses PORT env or 8080)
// load .env next to the server first — makes the upstash keys survive ANY restart path
try {
  const _envFs = require('fs'), _envPath = require('path');
  for (const _f of [_envPath.join(__dirname, '.env'), _envPath.join(process.cwd(), '.env')]) {
    if (_envFs.existsSync(_f)) {
      for (const _ln of _envFs.readFileSync(_f, 'utf8').split(/\r?\n/)) {
        const _m = _ln.match(/^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)\s*$/);
        if (_m && process.env[_m[1]] === undefined) process.env[_m[1]] = _m[2].replace(/^["']|["']$/g, '');
      }
      break;
    }
  }
} catch (e) {}

