var VD_WALLED = {}; SRCS.forEach(function(s, i){ if (s.w) VD_WALLED[i] = 1; });
// the vidsrc family (0,2,3,4,5) all front the same stellar player, which
// now demands a cloudflare turnstile token bound to its REAL domain - a
// proxied route (lite/tunnel) presents the door origin and can never be
