var autoTimer = null;
function playerAlive(){
  var seen = [];
  try { seen.push(document.getElementById('mvFrame').contentDocument); } catch (e) {}
  for (var d = 0; d < seen.length; d++) {
    var doc = seen[d]; if (!doc) continue;
    try {
      var vids = doc.querySelectorAll('video');
      for (var i = 0; i < vids.length; i++) { if (vids[i].readyState >= 2 || vids[i].currentTime > 0.05) return true; }
      var frs = doc.querySelectorAll('iframe');
      for (var j = 0; j < frs.length; j++) { try { if (frs[j].contentDocument) seen.push(frs[j].contentDocument); } catch (e) {} }
    } catch (e) {}
  }
  return false;
}
function chainSnap(){
  // fingerprint of the frame tree: every nested frame url + every
  // video readyState. if this keeps CHANGING, the chain is alive and
  // making progress — hands off, no matter how long it takes.
  var parts = [];
  var docs = [];
  try { docs.push(document.getElementById('mvFrame').contentDocument); } catch (e) {}
  for (var d = 0; d < docs.length; d++) {
    var doc = docs[d]; if (!doc) continue;
    try {
      parts.push(doc.URL || '');
      var vs = doc.querySelectorAll('video');
      for (var i = 0; i < vs.length; i++) parts.push('v' + vs[i].readyState);
      var frs = doc.querySelectorAll('iframe');
      for (var j = 0; j < frs.length; j++) { try { if (frs[j].contentDocument) docs.push(frs[j].contentDocument); } catch (e) {} }
    } catch (e) {}
  }
  return parts.join('|');
}
function deepestHost(){
  // where did the chain actually die? deepest readable frame, decoded
  // back to its real host — shown in the hint so a stall names its hop.
  var host = '';
  var docs = [];
  try { docs.push(document.getElementById('mvFrame').contentDocument); } catch (e) {}
  for (var d = 0; d < docs.length; d++) {
    var doc = docs[d]; if (!doc) continue;
    try {
      var u = String(doc.URL || '');
      var seg = '';
      var bi = u.indexOf('/browse/'), gi = u.indexOf('/gproxy/');
      var at = bi >= 0 ? bi + 8 : gi >= 0 ? gi + 8 : -1;
      if (at >= 0) { var rest = u.slice(at), cut = rest.length; ['/', '?', '&', '#'].forEach(function(c){ var p = rest.indexOf(c); if (p >= 0 && p < cut) cut = p; }); seg = rest.slice(0, cut); }
      if (seg) { try { var b = seg.split('-').join('+').split('_').join('/'); while (b.length % 4) b += '='; var dec = decodeURIComponent(escape(atob(b))); var h = dec.split('/')[2]; if (h) host = h; } catch (e) {} }
      else if (u && u.indexOf('about:') !== 0) { try { host = new URL(u).hostname || host; } catch (e) {} }
      var frs = doc.querySelectorAll('iframe');
      for (var j = 0; j < frs.length; j++) { try { if (frs[j].contentDocument) docs.push(frs[j].contentDocument); } catch (e) {} }
    } catch (e) {}
  }
  return host;
}
function armAuto(){
  // v239: the v235 walker was the bug — a flat 13s deadline, but a
  // virtual-direct chain is 5+ proxied hops before a <video> even
  // exists, so the walker kept murdering slow-but-working sources
  // mid-load and every movie died. now: check every 4s, and a source
  // only counts as dead after 30s of TOTAL stillness (no new frame,
  // no readyState movement). progress buys unlimited time.
  if (route === 'direct') return;
  if (autoTimer) clearTimeout(autoTimer);
  var lastSnap = chainSnap(), lastMove = Date.now();
  function tick(){
    autoTimer = null;
    try { if (libM) return; } catch (e) {}
    if (playerAlive()) { if (!aliveSaved) { aliveSaved = true; saveSrc(); } return; }
    var snap = chainSnap();
    if (snap !== lastSnap) { lastSnap = snap; lastMove = Date.now(); }
    if (Date.now() - lastMove < 30000) { autoTimer = setTimeout(tick, 4000); return; }
    var hint = document.getElementById('mvHint');
    var diedAt = deepestHost();
    var nxS = nextSrc(srcMode);
    if (nxS < SRCS.length) {
      var leftIx = srcMode;
      var leftState = lastScores ? lastScores[leftIx] : null;
      srcMode = nxS;
      syncSrcUI();
      if (hint) {
        if (leftState === 'dead') hint.textContent = SRCS[leftIx].n + ' is down for everyone — six checked';
        else if (leftState === 'alive') hint.textContent = SRCS[leftIx].n + ' looks up from here — your network may be blocking it (school wifi does this)';
        else hint.textContent = 'that source went quiet' + (diedAt ? ' at ' + diedAt : '') + ' — trying ' + SRCS[srcMode].n + ' (source ' + (srcMode + 1) + ' of ' + SRCS.length + ')…';
      }
      loadPlayer();
    } else if (hint) {
      hint.textContent = 'every source came up empty' + (diedAt ? ' (last one stalled at ' + diedAt + ')' : '') + ' — this one is prolly not out on streaming yet. new movies show up a while after theaters.';
    }
  }
  autoTimer = setTimeout(tick, 4000);
}
