function uvXorDecode(str){ try { var d = decodeURIComponent(str); var out = ''; for (var i = 0; i < d.length; i++) out += (i % 2) ? String.fromCharCode(d.charCodeAt(i) ^ 2) : d[i]; return out; } catch (e) { return ''; } }
